import {
  useCallback,
  useEffect,
  useLayoutEffect,
  useRef,
  useState,
  type RefObject,
} from "react";

/**
 * The Conversation Guidance feed's reading state — one unread system shared by
 * every card type in the column.
 *
 * The panel surfaces two kinds of card: response guidance the AI matched to a
 * moment in the call, and knowledge it retrieved to answer a question. They are
 * generated by different machinery and styled differently, but from the agent's
 * side there is one column and one question — *is there something here I have
 * not read yet?* So the count is one count. A card contributes to it whatever
 * kind it is, and it stops contributing the moment the agent has plainly had it
 * in front of them.
 *
 * "Plainly had it in front of them" is deliberately stricter than "it was on
 * screen once": half the card, held for `SEEN_DWELL_MS`. A card that flicks
 * past mid-scroll has not been read, and marking it read is how an agent loses
 * guidance without ever seeing it.
 *
 * The other half of the hook is the anchor. Nothing about a card arriving is
 * allowed to move the text under the agent's eyes — not by a pixel, not to
 * make room, not to show them the new thing. So the feed re-anchors on the
 * card they are looking at across every change to the list.
 */

/** Half the card. Matches the spec's IntersectionObserver threshold. */
const SEEN_RATIO = 0.5;
/** Held that long, not merely touched — scroll-past does not count as read. */
const SEEN_DWELL_MS = 300;
/**
 * Close enough to the growing end of the feed that the agent is watching it
 * grow rather than reading something else — the one case where letting a new
 * card into the visible column is what they want (§8).
 */
const EDGE_SLACK_PX = 40;

/**
 * Which end of the column new cards land at.
 *
 * The Conversation Guidance panel puts the newest card at the *top*: mid-call,
 * the thing that just became relevant is the thing to read, so it goes where
 * the eye already is. Guidance rendered inline in the script sheet is the other
 * way round — a card is placed under the script step it belongs to, so the feed
 * grows downward like a transcript.
 *
 * Everything about preserving the reading position depends on knowing which,
 * so it is declared rather than guessed. Get it wrong and the panel "preserves"
 * the position by scrolling away from it.
 */
export type FeedGrowth = "top" | "bottom";

/**
 * Is the agent parked at the end the feed grows from? A missing element reads
 * as yes: consumers that register no scroll container have no reading position
 * to protect, and keep the follow behaviour they had before this hook existed.
 */
export function isAtFeedGrowthEdge(
  feed: HTMLElement | null,
  growth: FeedGrowth,
  slack = EDGE_SLACK_PX
): boolean {
  if (!feed) return true;
  return growth === "top"
    ? feed.scrollTop <= slack
    : feed.scrollHeight - feed.scrollTop - feed.clientHeight <= slack;
}

interface CardView {
  /** Has been half-visible for the dwell — counted as read, permanently. */
  seen: boolean;
  /** Half-visible right now. Not yet read, but not "new" either (§8). */
  inView: boolean;
  /** Off-screen in the direction the feed grows — drives the "↓ 2 new" hint. */
  below: boolean;
}

const RESTING: CardView = { seen: false, inView: false, below: true };

/**
 * A card taller than the panel can never reach a 0.5 ratio of *itself*, so it
 * would never be marked read no matter how long the agent stared at it. Half
 * the viewport counts as half the card in that case.
 */
function isShowing(entry: IntersectionObserverEntry): boolean {
  if (!entry.isIntersecting) return false;
  if (entry.intersectionRatio >= SEEN_RATIO) return true;
  const root = entry.rootBounds;
  return Boolean(root && entry.intersectionRect.height >= root.height * SEEN_RATIO);
}

/** Which way the agent would have to scroll to reach it. */
function isBelow(entry: IntersectionObserverEntry): boolean {
  const root = entry.rootBounds;
  if (!root) return true;
  return entry.boundingClientRect.top >= root.top + root.height / 2;
}

/**
 * The card the agent is currently reading — the topmost one still on screen.
 *
 * Visibility is measured in viewport coordinates because those do not care
 * which ancestor happens to be positioned, but the remembered position is
 * `offsetTop`, which does not move when the column scrolls. Drift is then a
 * difference between two `offsetTop` readings, so whatever constant the
 * offset parent contributes cancels out.
 */
function anchorCard(
  feed: HTMLElement,
  nodes: Map<string, HTMLElement>
): { id: string; top: number } | null {
  const edge = feed.getBoundingClientRect().top;
  let best: { id: string; top: number; screenTop: number } | null = null;
  for (const [id, node] of nodes) {
    const rect = node.getBoundingClientRect();
    if (rect.bottom <= edge) continue;
    if (!best || rect.top < best.screenTop) {
      best = { id, top: node.offsetTop, screenTop: rect.top };
    }
  }
  return best ? { id: best.id, top: best.top } : null;
}

/**
 * Would this arrival push the card the agent is reading out from under them?
 *
 * In a top-growing feed the answer is yes whenever they have scrolled away
 * from the top at all — every arrival goes in above them. In a bottom-growing
 * one it depends on where the card lands: appended below the fold it disturbs
 * nothing, but placed against an earlier script step it can go in above the
 * viewport, and that is measured against the DOM.
 *
 * Where it is true the card still arrives and still counts as unread; what it
 * loses is the animation, because a quarter-second of the agent's own text
 * travelling is not worth an entrance they are not looking at (§18, §24).
 */
export function insertPushesViewport(
  feed: HTMLElement | null,
  growth: FeedGrowth,
  nodes: Map<string, HTMLElement>,
  ids: string[],
  index: number
): boolean {
  if (!feed) return false;
  if (growth === "top") return feed.scrollTop > EDGE_SLACK_PX;
  if (index >= ids.length) return false;
  const id = ids[index];
  const node = id === undefined ? undefined : nodes.get(id);
  if (!node) return false;
  return node.getBoundingClientRect().bottom <= feed.getBoundingClientRect().top;
}

export function useGuidanceFeed({
  feedRef,
  cardIds,
  growth,
  reduced,
  onNode,
}: {
  /** The scrolling column. Shared with `useGuidanceStream`. */
  feedRef: RefObject<HTMLElement | null>;
  /** Every card in the column, in the order it renders — both types. */
  cardIds: string[];
  growth: FeedGrowth;
  reduced: boolean;
  /** Passed the same nodes, so the stream can keep its own bookkeeping. */
  onNode?: (id: string, node: HTMLElement | null) => void;
}) {
  const nodes = useRef(new Map<string, HTMLElement>());
  /**
   * One ref callback per card id, cached. A fresh arrow per render would make
   * React detach and reattach the ref on every tick of the call clock, which
   * re-fires the observer and resets the dwell timer — a 200ms clock would
   * then keep a 300ms dwell from ever completing, and nothing would ever be
   * marked read.
   */
  const refs = useRef(new Map<string, (node: HTMLElement | null) => void>());
  const observer = useRef<IntersectionObserver | null>(null);
  const dwell = useRef(new Map<string, number>());
  const onNodeRef = useRef(onNode);
  onNodeRef.current = onNode;

  const [views, setViews] = useState<Map<string, CardView>>(new Map());

  const patch = useCallback((id: string, next: Partial<CardView>) => {
    setViews((current) => {
      const previous = current.get(id) ?? RESTING;
      const merged = { ...previous, ...next };
      if (
        merged.seen === previous.seen &&
        merged.inView === previous.inView &&
        merged.below === previous.below
      ) {
        return current;
      }
      const updated = new Map(current);
      updated.set(id, merged);
      return updated;
    });
  }, []);

  const clearDwell = useCallback((id: string) => {
    const timer = dwell.current.get(id);
    if (timer === undefined) return;
    window.clearTimeout(timer);
    dwell.current.delete(id);
  }, []);

  const cardRef = useCallback(
    (id: string) => {
      const cached = refs.current.get(id);
      if (cached) return cached;
      const ref = (node: HTMLElement | null) => {
        const known = nodes.current.get(id);
        if (node) {
          if (known === node) return;
          if (known) observer.current?.unobserve(known);
          node.dataset.cardId = id;
          nodes.current.set(id, node);
          observer.current?.observe(node);
        } else if (known) {
          observer.current?.unobserve(known);
          nodes.current.delete(id);
          clearDwell(id);
        }
        onNodeRef.current?.(id, node);
      };
      refs.current.set(id, ref);
      return ref;
    },
    [clearDwell]
  );

  // ---- seen / unseen -----------------------------------------------------
  useEffect(() => {
    const feed = feedRef.current;
    if (!feed) return;
    const io = new IntersectionObserver(
      (entries) => {
        for (const entry of entries) {
          const id = (entry.target as HTMLElement).dataset.cardId;
          if (!id) continue;
          const showing = isShowing(entry);
          patch(id, { inView: showing, below: showing ? false : isBelow(entry) });
          if (!showing) {
            clearDwell(id);
            continue;
          }
          if (dwell.current.has(id)) continue;
          dwell.current.set(
            id,
            window.setTimeout(() => {
              dwell.current.delete(id);
              patch(id, { seen: true });
            }, SEEN_DWELL_MS)
          );
        }
      },
      {
        root: feed,
        // Crossing 0.5 is the event we care about, but a card can enter and
        // leave without ever crossing it — a tall one, or one revealed by an
        // expand above it. The extra stops keep `below` honest meanwhile.
        threshold: [0, 0.25, SEEN_RATIO, 0.75, 1],
      }
    );
    observer.current = io;
    nodes.current.forEach((node) => io.observe(node));
    // Read into a local so the cleanup drops the timers this effect started
    // rather than whatever the ref points at by the time it runs.
    const pending = dwell.current;
    return () => {
      io.disconnect();
      observer.current = null;
      pending.forEach((timer) => window.clearTimeout(timer));
      pending.clear();
    };
  }, [feedRef, patch, clearDwell]);

  // ---- anchor ------------------------------------------------------------
  const anchor = useRef<{ id: string; top: number } | null>(null);
  const reanchor = useCallback(() => {
    const feed = feedRef.current;
    if (feed) anchor.current = anchorCard(feed, nodes.current);
  }, [feedRef]);

  /**
   * Re-read after every paint, not only when cards change. The column also
   * moves when the agent expands a card or scrolls, and an anchor that went
   * stale during either would hand the correction below a drift the agent
   * caused themselves — which it would then dutifully undo.
   */
  useEffect(reanchor);

  /**
   * The reading position outranks everything else the feed wants to do (§18),
   * so it is restored before the browser paints rather than corrected after.
   *
   * Keyed on the card list alone: an expand or a collapse moves the column too,
   * but the agent asked for that one, and compensating it would fight their own
   * click. Skipped at the growth edge for the same reason — there the agent is
   * watching the feed grow, and holding position would scroll them off the new
   * card they were waiting for (§8).
   */
  const key = cardIds.join("|");
  useLayoutEffect(() => {
    const feed = feedRef.current;
    if (!feed) return;
    const held = anchor.current;
    if (!held || isAtFeedGrowthEdge(feed, growth)) return;
    const node = nodes.current.get(held.id);
    if (!node) return;
    const drift = node.offsetTop - held.top;
    if (drift !== 0) feed.scrollTop += drift;
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [key]);

  // ---- derived -----------------------------------------------------------
  /**
   * Unread *and* not currently on screen. A card that lands in the visible
   * part of the feed is being read right now — counting it as "1 new" would
   * point the agent at something they are already looking at (§8).
   */
  const unseenIds = cardIds.filter((id) => {
    const view = views.get(id);
    return !view?.seen && !view?.inView;
  });
  const firstUnseenId = unseenIds[0] ?? null;
  /**
   * Which way to look. Named rather than assumed: in this panel the newest card
   * lands at the top, so the unread ones are usually *above* the agent, and an
   * arrow pointing down would send them the wrong way. `null` when the unread
   * cards are on both sides — no arrow beats a misleading one.
   */
  const sides = new Set(
    unseenIds.map((id) => (views.get(id)?.below === false ? "up" : "down"))
  );
  const unseenDirection = sides.size === 1 ? [...sides][0]! : null;

  const firstUnseenRef = useRef<string | null>(firstUnseenId);
  firstUnseenRef.current = firstUnseenId;

  return {
    /** Stable ref callback for a card of any type. */
    cardRef,
    unseenCount: unseenIds.length,
    firstUnseenId,
    /** "up" | "down" when every unread card is on one side, else null (§7). */
    unseenDirection,
    isAtGrowthEdge: () => isAtFeedGrowthEdge(feedRef.current, growth),
    /**
     * The agent asked to be taken to what they have not read. This is the only
     * scroll the panel performs that the agent did not perform themselves —
     * every other one is either theirs or suppressed.
     */
    revealFirstUnseen: () => {
      const id = firstUnseenRef.current;
      if (!id) return;
      nodes.current.get(id)?.scrollIntoView({
        behavior: reduced ? "auto" : "smooth",
        block: "nearest",
      });
      // Whatever it scrolls to is about to be on screen and read, so the
      // anchor that was holding the old position is spent.
      reanchor();
    },
  };
}
